WITH with_windows AS (SELECT *, NTILE(3) OVER (PARTITION BY location ORDER BY budget, id) AS budget_bucket, LEAD(budget, 1) OVER (PARTITION BY location ORDER BY budget, id) AS next_budget, FIRST_VALUE(location, TRUE) OVER (PARTITION BY dept_name ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_location, NTILE(3) OVER (ORDER BY budget, id) AS budget_bucket_2, COUNT(budget) OVER (PARTITION BY dept_name) AS dept_name_count_budget FROM departments) SELECT CASE WHEN budget_bucket >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END AS budget_bucket_tier, STDDEV_SAMP(budget) AS budget_stddev, SIZE(COLLECT_SET(location)) AS num_locations, SORT_ARRAY(COLLECT_SET(dept_name)) AS dept_name_list FROM with_windows GROUP BY CASE WHEN budget_bucket >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY num_locations DESC NULLS FIRST;
